<script setup lang="ts">
import {ref,onMounted} from 'vue';import {api,can,text,date,useTask,type DTO,type Page} from './shared';import PageState from './PageState.vue';
const {busy,error,run}=useTask(),resources=ref<DTO<'ResourceSummary'>[]>([]),cases=ref<DTO<'Stage2ChangeCaseView'>[]>([]),reminders=ref<DTO<'Stage2ReminderView'>[]>([]),connections=ref<DTO<'Stage2ConnectionView'>[]>([]),count=ref<number|null>(null),mine=ref<number|null>(null),active=ref<number|null>(null),unverified=ref<number|null>(null);
async function load(){await run(async()=>{
 const tasks=[
 async()=>{const d=await api.get<Page<DTO<'ResourceSummary'>>>('/resources?page_size=25');resources.value=d.items.slice(0,5);count.value=d.pagination.total;},
 async()=>{const d=await api.get<Page<DTO<'MyResourceSummary'>>>('/me/resources?page_size=25');mine.value=d.pagination.total;},
 async()=>{const d=await api.get<Page<DTO<'Stage2ChangeCaseView'>>>('/change-cases?status=active&page_size=25');cases.value=d.items.slice(0,5);active.value=d.pagination.total;},
 async()=>{const d=await api.get<Page<DTO<'Stage2ReminderView'>>>('/reminders?page_size=10');reminders.value=d.items;},
 async()=>{const d=await api.get<Page<DTO<'ResourceSummary'>>>('/resources?verification=unverified&page_size=25');unverified.value=d.pagination.total;},
 ];
 if(can('integration.manage'))tasks.push(async()=>{const d=await api.get<Page<DTO<'Stage2ConnectionView'>>>('/platform-connections?page_size=10');connections.value=d.items.filter(c=>c.stale||c.last_error_code);});
 const result=await Promise.allSettled(tasks.map(fn=>fn()));const failure=result.find(r=>r.status==='rejected');if(failure?.status==='rejected')throw failure.reason;
});}onMounted(load);
</script>
<template><header class="page-heading"><div><h1>工作台</h1><p>从当前可见资源、待办和到期事项开始。</p></div><button class="btn-secondary" :disabled="busy" @click="load">刷新</button></header><PageState :busy="busy" :error="error" @retry="load"/><div class="mb-4 grid grid-cols-3 gap-2"><RouterLink v-for="[title,value,path] in [['可见资源',count,'/resources'],['我的资源',mine,'/my-resources'],['进行中流程',active,'/governance']]" :key="title" :to="String(path)" class="feishu-section p-3 md:p-4"><p class="text-xs text-gray-500">{{title}}</p><p class="mt-1 text-2xl font-semibold text-gray-900">{{value??'—'}}</p></RouterLink></div><p v-if="unverified" class="mb-4 text-xs text-gray-500">当前有 {{unverified}} 条待核实记录。<RouterLink :to="{path:'/resources',query:{verification:'unverified'}}" class="text-link">查看待核实清单 →</RouterLink></p><div class="grid gap-4 lg:grid-cols-2"><section class="feishu-section"><div class="flex justify-between border-b p-3"><h2 class="text-sm font-medium">最近更新</h2><RouterLink to="/resources" class="text-link text-xs">全部资源 →</RouterLink></div><div v-if="!resources.length" class="p-5 text-sm text-gray-500">尚未登记资源。可从资源清单开始建档。</div><RouterLink v-for="r in resources" :key="r.id" :to="'/resources/'+r.id" class="flex items-center justify-between gap-2 border-b border-gray-100 px-4 py-3 hover:bg-gray-50"><div class="min-w-0"><p class="truncate text-sm font-medium">{{r.name}}</p><p class="mt-1 text-xs text-gray-500">{{text(r.type_code)}} · {{r.owner?.display_name??'责任待明确'}}</p></div><span class="shrink-0 text-xs text-gray-500">{{text(r.lifecycle)}}</span></RouterLink></section><section class="feishu-section"><div class="flex justify-between border-b p-3"><h2 class="text-sm font-medium">待处理流程</h2><RouterLink to="/governance" class="text-link text-xs">进入治理 →</RouterLink></div><p v-if="!cases.length" class="p-5 text-sm text-gray-500">当前没有进行中的可见流程。</p><RouterLink v-for="c in cases" :key="c.id" :to="{path:'/governance',query:{case:c.id}}" class="block border-b border-gray-100 px-4 py-3 hover:bg-gray-50"><p class="truncate text-sm">{{c.reason}}</p><p class="mt-1 text-xs text-gray-500">{{text(c.case_type)}} · {{c.status==='active'?'进行中':text(c.status)}} · {{date(c.created_at)}}</p></RouterLink></section><section class="feishu-section"><h2 class="border-b p-3 text-sm font-medium">到期提醒</h2><p v-if="!reminders.length" class="p-5 text-sm text-gray-500">没有可见的到期提醒。</p><RouterLink v-for="r in reminders" :key="r.id" :to="'/resources/'+r.resource_id" class="flex justify-between gap-2 border-b px-4 py-3 text-xs hover:bg-gray-50"><span>{{r.resource_name??'查看到期资源'}} · {{r.due_on}}</span><span>{{text(r.status)}} · {{r.read?'已读':'未读'}}</span></RouterLink></section><section v-if="can('integration.manage')" class="feishu-section"><h2 class="border-b p-3 text-sm font-medium">连接需要关注</h2><p v-if="!connections.length" class="p-5 text-sm text-gray-500">当前展示范围内没有异常或陈旧连接。</p><RouterLink v-for="c in connections" :key="c.id" :to="{path:'/subscriptions',query:{tab:'connections',connection:c.id}}" class="block border-b px-4 py-3 text-xs hover:bg-gray-50">{{c.label}} · {{c.last_error_code??'数据已陈旧'}}<p class="mt-1 text-gray-500">最近成功 {{date(c.last_success_at)}}</p></RouterLink><p class="px-4 py-2 text-[11px] text-gray-400">仅展示最近 10 条连接中的关注项。</p></section></div></template>
